"""Unit tests for the word-frequency counter utility."""

import os
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from wordfreq import main, top_words, word_frequencies  # noqa: E402


class WordFrequenciesTests(unittest.TestCase):
    def test_normal_text(self):
        self.assertEqual(
            word_frequencies("the quick brown fox jumps over the lazy dog"),
            {
                "the": 2,
                "quick": 1,
                "brown": 1,
                "fox": 1,
                "jumps": 1,
                "over": 1,
                "lazy": 1,
                "dog": 1,
            },
        )

    def test_punctuation_stripped(self):
        self.assertEqual(
            word_frequencies("Hello, world! (Hello) -- world."),
            {"hello": 2, "world": 2},
        )

    def test_case_insensitive(self):
        self.assertEqual(word_frequencies("The the THE"), {"the": 3})

    def test_empty_input(self):
        self.assertEqual(word_frequencies(""), {})

    def test_whitespace_only_input(self):
        self.assertEqual(word_frequencies("   \n\t  "), {})

    def test_punctuation_only_tokens_dropped(self):
        self.assertEqual(word_frequencies("-- ... !!!"), {})


class TopWordsTests(unittest.TestCase):
    def test_limit(self):
        text = "a b c d e"
        self.assertEqual(len(top_words(text, 3)), 3)

    def test_tie_break_alphabetical(self):
        text = "banana apple cherry apple banana cherry"
        self.assertEqual(
            top_words(text, 3),
            [("apple", 2), ("banana", 2), ("cherry", 2)],
        )

    def test_count_descending(self):
        text = "x x x y y z"
        self.assertEqual(top_words(text, 3), [("x", 3), ("y", 2), ("z", 1)])

    def test_non_positive_n(self):
        self.assertEqual(top_words("a b c", 0), [])
        self.assertEqual(top_words("a b c", -5), [])

    def test_n_larger_than_distinct(self):
        self.assertEqual(top_words("a b", 10), [("a", 1), ("b", 1)])


class CliTests(unittest.TestCase):
    def test_cli_smoke(self):
        fd, path = tempfile.mkstemp(suffix=".txt")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                handle.write("one two two three three three")
            self.assertEqual(main([path, "--top", "2"]), 0)
        finally:
            os.unlink(path)

    def test_cli_missing_file(self):
        self.assertEqual(main(["/nonexistent/path/xyz.txt"]), 2)

    def test_cli_bad_usage(self):
        self.assertEqual(main([]), 2)
        self.assertEqual(main(["a.txt", "--top", "notanint"]), 2)


if __name__ == "__main__":
    unittest.main()

