"""Unit tests for reports.word_frequency."""

import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from reports.word_frequency import tokenize, word_frequency  # noqa: E402


class WordFrequencyTests(unittest.TestCase):
    def test_basic_ranking(self):
        text = "apple banana apple cherry apple banana"
        self.assertEqual(
            word_frequency(text),
            [("apple", 3), ("banana", 2), ("cherry", 1)],
        )

    def test_case_insensitive(self):
        self.assertEqual(word_frequency("The the THE"), [])

    def test_case_insensitive_non_stopword(self):
        self.assertEqual(word_frequency("Dog dog DOG cat"), [("dog", 3), ("cat", 1)])

    def test_punctuation_stripped(self):
        self.assertEqual(
            word_frequency("hello, world! hello... world? world"),
            [("world", 3), ("hello", 2)],
        )

    def test_stopwords_excluded(self):
        text = "the quick brown fox and the lazy dog of the"
        words = [word for word, _ in word_frequency(text, top_n=10)]
        self.assertNotIn("the", words)
        self.assertNotIn("and", words)
        self.assertNotIn("of", words)
        self.assertEqual(words[0], "the" if False else "brown")

    def test_top_n_truncation_and_tie_break(self):
        text = "delta alpha charlie bravo alpha bravo charlie delta"
        # All counts equal -> alphabetical order, truncated to 2.
        self.assertEqual(
            word_frequency(text, top_n=2),
            [("alpha", 2), ("bravo", 2)],
        )

    def test_empty_input(self):
        self.assertEqual(word_frequency(""), [])
        self.assertEqual(word_frequency("   \n\t "), [])

    def test_non_positive_top_n(self):
        self.assertEqual(word_frequency("apple apple", top_n=0), [])
        self.assertEqual(word_frequency("apple apple", top_n=-3), [])

    def test_top_n_larger_than_distinct_words(self):
        self.assertEqual(word_frequency("apple banana", top_n=99), [("apple", 1), ("banana", 1)])

    def test_tokenize(self):
        self.assertEqual(tokenize("Hello, World!"), ["hello", "world"])


if __name__ == "__main__":
    unittest.main()

