"""Core word-frequency counting logic."""

from __future__ import annotations

from collections import Counter


def _strip_edges(token: str) -> str:
    """Strip leading/trailing non-alphanumeric characters (unicode-safe)."""
    start = 0
    end = len(token)
    while start < end and not token[start].isalnum():
        start += 1
    while end > start and not token[end - 1].isalnum():
        end -= 1
    return token[start:end]


def word_frequency(text: str) -> dict[str, int]:
    """Return a mapping of word -> occurrence count for ``text``.

    Words are lowercased, split on whitespace, and have leading/trailing
    non-alphanumeric characters removed. Tokens that become empty are
    dropped. Empty or whitespace-only input yields an empty dict.
    """
    if not text or not text.strip():
        return {}

    counts: Counter[str] = Counter()
    for raw in text.lower().split():
        token = _strip_edges(raw)
        if token:
            counts[token] += 1
    return dict(counts)

